110	export function billFirstInvoice(state: State, sub: Subscription, now: number): Invoice {
111	  const id = mint(state, "in");
112	  const trial = sub.status === "trialing";
113	  const specs = trial ? [] : specsOf(state, sub.discounts);
114	  const lines: Line[] = sub.items.map((it) => {
115	    const p = priceOf(state, it.price);
116	    return {
117	      id: mint(state, "il"),
118	      amount: trial ? 0 : p.unit_amount * it.quantity,
119	      description: trial
120	        ? `Free trial for ${it.quantity} × ${productName(state, it.price)}`
121	        : recurringDescription(state, it.price, it.quantity),
122	      period: { start: sub.period_start, end: sub.period_end },
123	      price: it.price,
124	      quantity: it.quantity,
125	      proration: false,
126	      discountable: true,
127	      discount_amounts: [],
128	      subscription_item: it.id,
129	      invoice_item: null,
130	      credited: null,
131	      unit_amount_decimal: String(p.unit_amount),
132	    };
133	  });
134	  const alloc = allocate(
135	    lines.map((l) => l.amount),
136	    specs,
137	  );
138	  lines.forEach((l, i) => {
139	    l.discount_amounts = specs.map((s, k) => ({ discount: s.id, amount: alloc[k]?.[i] ?? 0 }));
140	  });
141	  sub.items.forEach((it, i) => {
142	    const l = lines[i];
143	    if (l) it.billed = { invoice: id, line: l.id, amount: l.amount, discounts: l.discount_amounts };
144	  });
145	  spendOnce(state, specs, alloc);
146	  const tda = specs.map((s, k) => ({
147	    discount: s.id,
148	    amount: (alloc[k] ?? []).reduce((a, b) => a + b, 0),
149	  }));
150	  const inv: Invoice = {
151	    id,
152	    customer: sub.customer,
153	    subscription: sub.id,
154	    lines,
155	    discounts: specs.map((s) => s.id),
156	    total_discount_amounts: tda,
157	    billing_reason: "subscription_create",
158	    status: "paid",
159	    created: now,
160	    period_start: now,
161	    period_end: now,
162	    attempt_count: 0,
163	    amount_paid: 0,
164	    auto_advance: false,
165	    next_payment_attempt: null,
166	    proration_date: null,
167	    retries: [],
168	    starting_balance: 0,
169	    deferred: 0,
170	    finalized_at: null,
171	    paid_at: null,
172	    manual: false,
173	  };
174	  if (!deferSmall(state, inv)) {
175	    const due = amountDue(inv);
176	    inv.amount_paid = due;
177	    inv.attempt_count = due > 0 ? 1 : 0;
178	  }
179	  inv.finalized_at = now;
180	  inv.paid_at = now;
181	  state.invoices[id] = inv;
182	  sub.latest_invoice = id;
183	  return inv;
184	}
