188	function createSubscription(state: State, p: Params): CloneResponse {
189	  const customerId = str(p.customer) ?? "";
190	  const customer = get(state.customers, customerId);
191	  if (!customer) return missing("customer", customerId);
192	  const now = nowFor(state, customerId);
193	  const id = mint(state, "sub");
194	  const items = arr(p.items).map((raw) => {
195	    const it = obj(raw);
196	    return {
197	      id: mint(state, "si"),
198	      price: str(it.price) ?? "",
199	      quantity: num(it.quantity) ?? 1,
200	      created: now,
201	      billed: null,
202	    };
203	  });
204	  for (const it of items) if (!get(state.prices, it.price)) return missing("price", it.price);
205	  const first = items[0];
206	  const interval: Interval = first ? priceOf(state, first.price).interval : "month";
207	  const trialDays = num(p.trial_period_days);
208	  const trialEnd = trialDays !== null ? now + trialDays * 86400 : null;
209	  const mode = str(obj(p.billing_mode).type) === "classic" ? "classic" : "flexible";
210	  const sub: Subscription = {
211	    id,
212	    customer: customerId,
213	    items,
214	    billing_mode: mode,
215	    discounts: [],
216	    anchor: trialEnd ?? now,
217	    period_start: now,
218	    period_end: trialEnd ?? addIntervals(now, interval, 1),
219	    status: trialEnd !== null ? "trialing" : "active",
220	    created: now,
221	    latest_invoice: null,
222	    cancel_at_period_end: false,
223	    cancel_at: null,
224	    canceled_at: null,
225	    ended_at: null,
226	    natural_end: null,
227	    trial_start: trialEnd !== null ? now : null,
228	    trial_end: trialEnd,
229	    cancellation_reason: null,
230	    metadata: {},
231	  };
232	  for (const raw of arr(p.discounts)) {
233	    const coupon = str(obj(raw).coupon) ?? "";
234	    if (!get(state.coupons, coupon)) return missing("coupon", coupon);
235	    sub.discounts.push(newDiscount(state, coupon, customerId, id, now).id);
236	  }
237	  state.subscriptions[id] = sub;
238	  customer.currency ??= "usd";
239	  billFirstInvoice(state, sub, now);
240	  return ok(subscriptionJson(state, sub, false));
241	}
