312	// A change of items made for real (POST subscription or subscription item): the prorations become
313	// pending invoice items (create_prorations), an invoice now (always_invoice), or nothing (none).
314	function applyChange(
315	  state: State,
316	  sub: Subscription,
317	  changes: ItemChange[],
318	  p: Params,
319	): CloneResponse | null {
320	  const raw = str(p.proration_behavior);
321	  const behavior = raw !== null && BEHAVIORS.includes(raw) ? (raw as Behavior) : null;
322	  const now = nowFor(state, sub.customer);
323	  const plan = planChange(state, sub, {
324	    changes,
325	    proration_date: num(p.proration_date),
326	    behavior,
327	    discounts: null,
328	    now,
329	  });
330	  if (isPlanError(plan)) return fail(400, plan.message, plan.param);
331	  for (const l of plan.prorations) addPending(state, sub, l, now);
332	  sub.items.forEach((it) => {
333	    const next = plan.items.find((x) => x.id === it.id);
334	    if (next) {
335	      it.price = next.price;
336	      it.quantity = next.quantity;
337	    }
338	  });
339	  if (plan.reset) {
340	    sub.anchor = plan.anchor;
341	    sub.period_start = plan.period_start;
342	    sub.period_end = plan.period_end;
343	  }
344	  if (plan.immediate) invoiceNow(state, sub, now);
345	  return null;
346	}
