351	function updateSubscription(state: State, sub: Subscription, p: Params): CloneResponse {
352	  const now = nowFor(state, sub.customer);
353	  if (p.coupon !== undefined && sub.billing_mode === "flexible") {
354	    return fail(400, LEGACY_COUPON);
355	  }
356	  const coupons: string[] | null =
357	    p.discounts !== undefined
358	      ? arr(p.discounts).map((raw) => str(obj(raw).coupon) ?? "")
359	      : p.coupon !== undefined
360	        ? [str(p.coupon) ?? ""].filter((c) => c !== "")
361	        : null;
362	  if (coupons) {
363	    for (const c of coupons) if (!get(state.coupons, c)) return missing("coupon", c);
364	  }
365	  if (p.items !== undefined) {
366	    const changes: ItemChange[] = arr(p.items).map((raw) => {
367	      const it = obj(raw);
368	      return { id: str(it.id) ?? "", price: str(it.price), quantity: num(it.quantity) };
369	    });
370	    for (const ch of changes) {
371	      if (!sub.items.some((it) => it.id === ch.id)) return missing("subscription_item", ch.id);
372	      if (ch.price !== null && !get(state.prices, ch.price)) return missing("price", ch.price);
373	    }
374	    const failed = applyChange(state, sub, changes, p);
375	    if (failed) return failed;
376	  }
377	  if (coupons) {
378	    sub.discounts = coupons.map((c) => newDiscount(state, c, sub.customer, sub.id, now).id);
379	  }
380	  if (p.cancel_at_period_end !== undefined) {
381	    const on = bool(p.cancel_at_period_end);
382	    sub.cancel_at_period_end = on;
383	    sub.cancel_at = on ? sub.period_end : null;
384	    sub.canceled_at = on ? now : null;
385	    sub.cancellation_reason = on ? "cancellation_requested" : null;
386	  }
387	  // metadata[k]=v sets a key, an empty value removes it.
388	  const merged = new Map<string, string>(Object.entries(sub.metadata));
389	  for (const [k, v] of Object.entries(obj(p.metadata))) merged.set(k, str(v) ?? "");
390	  const kept: Record<string, string> = {};
391	  for (const [k, v] of merged) if (v !== "") kept[k] = v;
392	  sub.metadata = kept;
393	  // LIF-08: cancel_at sets the end date (cancel_at_period_end stays false, even at the period
394	  // end); an empty value clears it, like reactivating.
395	  if (p.cancel_at !== undefined) {
396	    const at = num(p.cancel_at);
397	    cancelInsidePeriod(state, sub, at, p, now);
398	    sub.cancel_at_period_end = false;
399	    sub.cancel_at = at;
400	    sub.canceled_at = at !== null ? now : null;
401	    sub.cancellation_reason = at !== null ? "cancellation_requested" : null;
402	  }
403	  return ok(subscriptionJson(state, sub, false));
404	}
