406	// LIF-09: a cancel_at inside the current period ends the period there at once; unless
407	// proration_behavior is none, the unused time after it is credited now, as a pending item. Clearing
408	// cancel_at restores the period end (the credit, if any, is left as is: not pinned).
409	function cancelInsidePeriod(
410	  state: State,
411	  sub: Subscription,
412	  at: number | null,
413	  p: Params,
414	  now: number,
415	): void {
416	  if (at === null) {
417	    if (sub.natural_end !== null) sub.period_end = sub.natural_end;
418	    sub.natural_end = null;
419	    return;
420	  }
421	  if (at >= sub.period_end || at < now) return;
422	  if (str(p.proration_behavior) !== "none") {
423	    for (const it of sub.items) {
424	      if (priceOf(state, it.price).unit_amount * it.quantity === 0) continue;
425	      const credit = creditLine(state, sub, it, at).line;
426	      addPending(state, sub, { ...credit, detached: true }, now);
427	    }
428	  }
429	  sub.natural_end ??= sub.period_end;
430	  sub.period_end = at;
431	}
