537	export function handleApi(state: State, req: CloneRequest, p: Params): CloneResponse | null {
538	  const parts = req.path.split("/").filter((s) => s !== "");
539	  if (parts[0] !== "v1") return null;
540	  const [, a, b, c, d] = parts;
541	  const m = req.method;
542	
543	  if (a === "test_helpers" && b === "test_clocks") {
544	    if (m === "POST" && c === undefined) {
545	      const id = mint(state, "clock");
546	      const t = num(p.frozen_time) ?? 0;
547	      state.clocks[id] = { id, frozen_time: t, created: t };
548	      return ok(clockJson(state, id));
549	    }
550	    const clock = c !== undefined ? get(state.clocks, c) : undefined;
551	    if (!clock || c === undefined) return missing("test_clock", c ?? "");
552	    if (m === "GET") return ok(clockJson(state, c));
553	    if (m === "POST" && d === "advance") {
554	      advanceClock(state, clock, num(p.frozen_time) ?? clock.frozen_time);
555	      return ok(clockJson(state, c));
556	    }
557	  }
558	  if (a === "products" && m === "POST" && b === undefined) {
559	    const id = mint(state, "prod");
560	    state.products[id] = { id, name: str(p.name) ?? "" };
561	    return ok({ id, object: "product", name: str(p.name) ?? "", active: true });
