575	  }
576	  if (a === "prices" && m === "GET" && b !== undefined) {
577	    return get(state.prices, b) ? ok(priceJson(state, b)) : missing("price", b);
578	  }
579	  if (a === "subscription_items") return subscriptionItems(state, req, p, b);
580	  if (a === "coupons" && m === "POST" && b === undefined) {
581	    const id = mint(state, "coupon");
