590	    return ok(couponJson(coupon));
591	  }
592	  if (a === "customers") {
593	    if (m === "POST" && b === undefined) {
594	      const id = mint(state, "cus");
595	      const clock = str(p.test_clock);
596	      const now = clock ? (get(state.clocks, clock)?.frozen_time ?? 0) : 0;
597	      const pmToken = str(p.payment_method);
598	      const pm = pmToken ? paymentMethodFrom(state, pmToken, id) : null;
599	      const cus = {
600	        id,
601	        clock,
602	        default_payment_method: pm,
603	        created: now,
604	        balance: 0,
605	        currency: null,
606	        invoice_prefix: invoicePrefix(state.n),
607	        preferred_locales: arr(p.preferred_locales).map((x) => str(x) ?? ""),
608	      };
