610	      return ok(customerJson(state, cus));
611	    }
612	    const cus = b !== undefined ? get(state.customers, b) : undefined;
613	    if (!cus || b === undefined) return missing("customer", b ?? "");
614	    if (m === "POST" && c === undefined) {
615	      const dpm = str(obj(p.invoice_settings).default_payment_method);
616	      if (dpm) cus.default_payment_method = paymentMethodFrom(state, dpm, cus.id);
617	    }
618	    return ok(customerJson(state, cus));
619	  }
620	  if (a === "payment_methods" && b !== undefined && c === "attach" && m === "POST") {
621	    const id = paymentMethodFrom(state, b, str(p.customer));
622	    return ok({ id, object: "payment_method", customer: str(p.customer), type: "card" });
623	  }
624	  if (a === "subscriptions") {
625	    if (m === "POST" && b === undefined) return createSubscription(state, p);
626	    if (m === "GET" && b === undefined) return listSubscriptions(state, p);
627	    const sub = b !== undefined ? get(state.subscriptions, b) : undefined;
628	    if (!sub || b === undefined) return missing("subscription", b ?? "");
629	    if (m === "GET") return ok(expandedSubscription(state, sub, p));
630	    if (m === "DELETE") {
631	      cancelNow(state, sub, bool(p.prorate), bool(p.invoice_now));
632	      return ok(subscriptionJson(state, sub, false));
633	    }
634	    if (m === "POST") {
635	      const res = updateSubscription(state, sub, p);
636	      return res.status === 200 ? ok(expandedSubscription(state, sub, p)) : res;
637	    }
638	  }
639	  if (a === "invoices") {
640	    if (m === "POST" && b === "create_preview") return previewInvoice(state, p);
641	    if (m === "POST" && b === undefined) return createInvoice(state, p);
642	    if (m === "GET" && b === "upcoming") return fail(400, UPCOMING_GONE);
643	    if (m === "GET" && b === undefined) return listInvoices(state, p);
644	    if (m === "GET" && b !== undefined) {
645	      const inv = get(state.invoices, b);
646	      return inv ? ok(invoiceJson(state, inv, false)) : missing("invoice", b);
647	    }
648	  }
649	  if (a === "invoiceitems") {
650	    if (m === "GET" && b === undefined) return listInvoiceItems(state, p);
651	    if (m === "POST" && b === undefined) return createInvoiceItem(state, p);
652	    if (b !== undefined) {
653	      const ii = get(state.invoice_items, b);
