671	// Objects outside test clocks (prices, coupons, a clock-less customer's items) are stamped with
672	// wall-clock time on Stripe (recorded as noise); the clone uses the latest clock time, so that
673	// the same calls after a reset give the same output.
674	function latestClockTime(state: State): number {
675	  return Math.max(0, ...Object.values(state.clocks).map((c) => c.frozen_time));
676	}
