682	// ITM-02: a one-off invoice item, priced by a new price of a new product, pending until an invoice
683	// takes it.
684	function createInvoiceItem(state: State, p: Params): CloneResponse {
685	  const customer = str(p.customer) ?? "";
686	  if (!get(state.customers, customer)) return missing("customer", customer);
687	  const amount = num(p.amount) ?? 0;
688	  const now = customerNow(state, customer);
689	  const product = mint(state, "prod");
690	  state.products[product] = { id: product, name: "" };
691	  const price = mint(state, "price");
692	  state.prices[price] = {
693	    id: price,
694	    product,
695	    unit_amount: amount,
696	    currency: str(p.currency) ?? "usd",
697	    interval: "month",
698	    created: now,
699	  };
700	  const subscription = str(p.subscription);
701	  if (subscription !== null && !get(state.subscriptions, subscription)) {
702	    return missing("subscription", subscription);
703	  }
704	  const id = mint(state, "ii");
705	  state.invoice_items[id] = {
706	    id,
707	    customer,
708	    oneoff: true,
709	    subscription,
710	    invoice: null,
711	    date: now,
712	    line: {
713	      id: "",
714	      amount,
715	      description: str(p.description),
716	      period: { start: now, end: now },
717	      price,
718	      quantity: 1,
719	      proration: false,
720	      discountable: true,
721	      discount_amounts: [],
722	      subscription_item: null,
723	      invoice_item: id,
724	      credited: null,
725	      unit_amount_decimal: String(amount),
726	    },
727	  };
728	  return ok(invoiceItemJson(state, state.invoice_items[id]));
729	}
