731	// ITM-02: a new amount is priced by a new price of the same product; a description replaces the
732	// old one.
733	function updateInvoiceItem(state: State, ii: InvoiceItem, p: Params): InvoiceItem {
734	  const amount = num(p.amount);
735	  if (amount !== null) {
736	    const old = priceOf(state, ii.line.price);
737	    const price = mint(state, "price");
738	    state.prices[price] = { ...old, id: price, unit_amount: amount };
739	    ii.line = { ...ii.line, amount, price, unit_amount_decimal: String(amount) };
740	  }
741	  if (p.description !== undefined) ii.line = { ...ii.line, description: str(p.description) };
742	  return ii;
743	}
