745	// INV-02: POST /v1/invoices makes a draft (billing_reason manual). With
746	// pending_invoice_items_behavior=include it takes the customer's pending invoice items. With
747	// auto_advance it is finalized and paid an hour after creation (next_payment_attempt); without,
748	// it stays a draft.
749	function createInvoice(state: State, p: Params): CloneResponse {
750	  const customer = str(p.customer) ?? "";
751	  const cus = get(state.customers, customer);
752	  if (!cus) return missing("customer", customer);
753	  const now = customerNow(state, customer);
754	  const auto = bool(p.auto_advance);
755	  const current = Object.values(state.subscriptions)
756	    .filter((s) => s.customer === customer && s.status !== "canceled")
757	    .at(-1);
758	  const id = mint(state, "in");
759	  const lines: Line[] = [];
760	  if (str(p.pending_invoice_items_behavior) === "include") {
761	    for (const ii of Object.values(state.invoice_items)) {
762	      if (ii.customer !== customer || ii.invoice !== null) continue;
763	      ii.invoice = id;
764	      lines.push({ ...ii.line, id: mint(state, "il") });
765	    }
766	  }
767	  const inv: Invoice = {
768	    id,
769	    customer,
770	    subscription: null,
771	    lines,
772	    discounts: [],
773	    total_discount_amounts: [],
774	    billing_reason: "manual",
775	    status: "draft",
776	    created: now,
777	    // The current period of the customer's subscription (dev-v5-manual-invoice-mid-period);
778	    // without one, creation to one month later.
779	    period_start: current ? current.period_start : now,
780	    period_end: current ? current.period_end : addIntervals(now, "month", 1),
781	    attempt_count: 0,
782	    amount_paid: 0,
783	    auto_advance: auto,
784	    next_payment_attempt: auto ? now + 3600 : null,
785	    proration_date: null,
786	    retries: [],
787	    starting_balance: 0,
788	    deferred: 0,
789	    finalized_at: null,
790	    paid_at: null,
791	    manual: true,
792	  };
793	  state.invoices[id] = inv;
794	  return ok(invoiceJson(state, inv, false));
795	}
