797	// An 8-letter invoice prefix, deterministic (recorded as noise).
798	function invoicePrefix(n: number): string {
799	  let x = n * 2654435761;
800	  let s = "";
801	  for (let i = 0; i < 8; i += 1) {
802	    s += String.fromCharCode(65 + (x % 26));
803	    x = Math.floor(x / 26) + 7 * (i + 1);
804	  }
805	  return s;
806	}
