808	function clockJson(state: State, id: string): Json {
809	  const c = get(state.clocks, id);
810	  return {
811	    id,
812	    object: "test_helpers.test_clock",
813	    created: c?.created ?? 0,
814	    frozen_time: c?.frozen_time ?? 0,
815	    livemode: false,
816	    status: "ready",
817	  };
818	}
