49	// A proration line waiting for the next invoice, as an invoice item created at `now`.
50	export function addPending(
51	  state: State,
52	  sub: Subscription,
53	  line: Omit<Line, "id" | "invoice_item">,
54	  now: number,
55	): string {
56	  const id = mint(state, "ii");
