75	    customer: sub.customer,
76	    subscription: sub.id,
77	    lines,
78	    discounts: [],
79	    total_discount_amounts: [],
80	    billing_reason: "subscription_update",
81	    status: "draft",
82	    created: now,
83	    period_start: now,
84	    period_end: now,
85	    attempt_count: 0,
