108	// Pending invoice items a subscription's next invoice takes: its prorations and one-off items
109	// created for it, and the customer's one-off items not tied to a subscription (INV-03).
110	export function pendingFor(state: State, sub: Subscription): InvoiceItem[] {
111	  return Object.values(state.invoice_items).filter(
112	    (ii) =>
113	      ii.invoice === null &&
114	      (ii.subscription === sub.id ||
115	        (ii.oneoff && ii.subscription === null && ii.customer === sub.customer)),
116	  );
117	}
