119	// Pending invoice items of a subscription, moved onto an invoice.
120	export function takePending(state: State, sub: Subscription, invoice: string): Line[] {
121	  const out: Line[] = [];
122	  for (const ii of pendingFor(state, sub)) {
123	    ii.invoice = invoice;
124	    out.push({ ...ii.line, id: mint(state, "il") });
125	  }
126	  return out;
127	}
