129	function renew(state: State, sub: Subscription): void {
130	  const start = sub.period_end;
131	  const interval = priceOf(state, sub.items[0]?.price ?? "").interval;
132	  const end = periodAt(sub.anchor, interval, start)[1];
133	  const id = mint(state, "in");
134	  const pending = takePending(state, sub, id);
135	  const lines: Line[] = sub.items.map((it) => {
136	    const p = priceOf(state, it.price);
137	    return {
138	      id: mint(state, "il"),
139	      amount: p.unit_amount * it.quantity,
140	      description: recurringDescription(state, it.price, it.quantity),
141	      period: { start, end },
142	      price: it.price,
143	      quantity: it.quantity,
144	      proration: false,
145	      discountable: true,
146	      discount_amounts: [],
147	      subscription_item: it.id,
148	      invoice_item: null,
149	      credited: null,
150	      unit_amount_decimal: String(p.unit_amount),
151	    };
152	  });
153	  const active = sub.discounts.filter((d) => {
154	    const s = specOf(state, d);
155	    return s !== undefined && !(s.once && get(state.discounts, d)?.used === true);
156	  });
157	  const specs = specsOf(state, active);
158	  const alloc = allocate(
159	    lines.map((l) => l.amount),
160	    specs,
161	  );
162	  lines.forEach((l, i) => {
163	    l.discount_amounts = specs.map((s, k) => ({ discount: s.id, amount: alloc[k]?.[i] ?? 0 }));
164	  });
165	  spendOnce(state, specs, alloc);
166	  sub.items.forEach((it, i) => {
167	    const l = lines[i];
168	    if (l) it.billed = { invoice: id, line: l.id, amount: l.amount, discounts: l.discount_amounts };
169	  });
170	  const all = [...pending, ...lines];
171	  const inv: Invoice = {
172	    id,
173	    customer: sub.customer,
174	    subscription: sub.id,
175	    lines: all,
176	    discounts: specs.map((s) => s.id),
177	    total_discount_amounts: specs.map((s, k) => ({
178	      discount: s.id,
179	      amount: (alloc[k] ?? []).reduce((a, b) => a + b, 0),
180	    })),
181	    billing_reason: "subscription_cycle",
182	    status: "draft",
183	    created: start,
184	    period_start: sub.period_start,
185	    period_end: start,
186	    attempt_count: 0,
187	    amount_paid: 0,
188	    auto_advance: true,
189	    next_payment_attempt: start + HOUR,
190	    proration_date: null,
191	    retries: [],
192	    starting_balance: 0,
193	    deferred: 0,
194	    finalized_at: null,
195	    paid_at: null,
196	    manual: false,
197	  };
198	  // The customer balance moves onto the renewal invoice; a credit beyond its total stays.
199	  const cus = get(state.customers, sub.customer);
200	  if (cus) {
201	    inv.starting_balance = cus.balance;
202	    cus.balance = Math.min(0, invoiceTotal(inv) + cus.balance);
203	  }
204	  state.invoices[id] = inv;
205	  sub.latest_invoice = id;
206	  sub.period_start = start;
207	  sub.period_end = end;
208	  if (sub.status === "trialing") sub.status = "active";
209	}
