211	function attempt(state: State, inv: Invoice, at: number): void {
212	  const sub = inv.subscription ? get(state.subscriptions, inv.subscription) : undefined;
213	  const due = amountDue(inv);
214	  inv.finalized_at ??= at;
215	  if (due === 0 || deferSmall(state, inv)) {
216	    inv.status = "paid";
217	    inv.paid_at = at;
218	    inv.next_payment_attempt = null;
219	    inv.auto_advance = false;
220	    return;
221	  }
222	  inv.attempt_count += 1;
223	  if (!failing(state, inv.customer)) {
224	    inv.status = "paid";
225	    inv.paid_at = at;
226	    inv.amount_paid = due;
227	    inv.next_payment_attempt = null;
228	    inv.auto_advance = false;
229	    if (sub?.status === "past_due") sub.status = "active";
230	    return;
231	  }
232	  inv.status = "open";
233	  if (inv.attempt_count === 1) inv.retries = RETRIES.map((d) => at + d);
234	  const next = inv.retries.shift();
235	  inv.next_payment_attempt = next ?? null;
236	  if (sub && sub.status !== "canceled") sub.status = "past_due";
237	}
