239	// Runs every event of the clock's customers up to `to`, in time order.
240	export function advanceClock(state: State, clock: Clock, to: number): void {
241	  const customers = new Set(
242	    Object.values(state.customers)
243	      .filter((c) => c.clock === clock.id)
244	      .map((c) => c.id),
245	  );
246	  for (let guard = 0; guard < 1000; guard += 1) {
247	    const events: { at: number; run: () => void }[] = [];
248	    const consider = (at: number, run: () => void): void => {
249	      if (at <= to) events.push({ at, run });
250	    };
251	    for (const sub of Object.values(state.subscriptions)) {
252	      if (!customers.has(sub.customer) || sub.status === "canceled") continue;
253	      const cancelAt = sub.cancel_at;
254	      if (cancelAt !== null && cancelAt <= sub.period_end) {
255	        consider(cancelAt, () => {
256	          sub.status = "canceled";
257	          sub.ended_at = cancelAt;
258	          finalInvoice(state, sub, cancelAt);
259	        });
260	        continue;
261	      }
262	      consider(sub.period_end, () => {
263	        if (sub.cancel_at_period_end) {
264	          sub.status = "canceled";
265	          sub.ended_at = sub.period_end;
266	        } else {
267	          renew(state, sub);
268	        }
269	      });
270	    }
271	    for (const inv of Object.values(state.invoices)) {
272	      if (!customers.has(inv.customer)) continue;
273	      if ((inv.status === "draft" && inv.auto_advance) || inv.status === "open") {
274	        const at = inv.next_payment_attempt;
275	        if (at !== null) {
276	          consider(at, () => {
277	            attempt(state, inv, at);
278	          });
279	        }
280	      }
281	    }
282	    // The earliest event first; ties keep discovery order (subscriptions before invoices).
283	    const chosen = events.reduce<{ at: number; run: () => void } | null>(
284	      (best, e) => (best === null || e.at < best.at ? e : best),
285	      null,
286	    );
287	    if (chosen === null) break;
288	    clock.frozen_time = Math.max(clock.frozen_time, chosen.at);
289	    chosen.run();
290	  }
291	  clock.frozen_time = to;
292	}
