294	// LIF-09: when a subscription ends at cancel_at, its pending items (the credit for the unused time
295	// included) go on a last subscription_cycle invoice, finalized and paid an hour later.
296	function finalInvoice(state: State, sub: Subscription, at: number): void {
297	  if (pendingFor(state, sub).length === 0) return;
298	  const id = mint(state, "in");
299	  const inv: Invoice = {
300	    id,
301	    customer: sub.customer,
302	    subscription: sub.id,
303	    lines: takePending(state, sub, id),
304	    discounts: [],
305	    total_discount_amounts: [],
306	    billing_reason: "subscription_cycle",
307	    status: "draft",
308	    created: at,
309	    period_start: sub.period_start,
310	    period_end: at,
311	    attempt_count: 0,
312	    amount_paid: 0,
313	    auto_advance: true,
314	    next_payment_attempt: at + HOUR,
315	    proration_date: null,
316	    retries: [],
317	    starting_balance: 0,
318	    deferred: 0,
319	    finalized_at: null,
320	    paid_at: null,
321	    manual: false,
322	  };
323	  const cus = get(state.customers, sub.customer);
324	  if (cus) {
325	    inv.starting_balance = cus.balance;
326	    cus.balance = Math.min(0, invoiceTotal(inv) + cus.balance);
327	  }
328	  state.invoices[id] = inv;
329	  sub.latest_invoice = id;
330	}
331	
332	export function cancelNow(
333	  state: State,
334	  sub: Subscription,
335	  prorate: boolean,
336	  invoiceNow: boolean,
337	): void {
338	  const now = nowFor(state, sub.customer);
339	  if (prorate && now < sub.period_end) {
340	    const credits = sub.items.map((it) => creditLine(state, sub, it, now).line);
341	    if (invoiceNow) {
342	      const id = mint(state, "in");
343	      const pending = takePending(state, sub, id);
344	      const lines: Line[] = [
345	        ...pending,
346	        ...credits.map((l) => ({ ...l, id: mint(state, "il"), invoice_item: mint(state, "ii") })),
347	      ];
348	      state.invoices[id] = {
349	        id,
350	        customer: sub.customer,
351	        subscription: sub.id,
352	        lines,
353	        discounts: [],
354	        total_discount_amounts: [],
355	        billing_reason: "subscription_cycle",
356	        status: "draft",
357	        created: now,
358	        period_start: sub.period_start,
359	        period_end: now,
360	        attempt_count: 0,
361	        amount_paid: 0,
362	        auto_advance: false,
363	        next_payment_attempt: null,
364	        proration_date: null,
365	        retries: [],
366	        starting_balance: 0,
367	        deferred: 0,
368	        finalized_at: null,
369	        paid_at: null,
370	        manual: false,
371	      };
372	      sub.latest_invoice = id;
373	    } else {
374	      for (const l of credits) addPending(state, sub, l, now);
375	    }
376	  }
377	  sub.status = "canceled";
378	  sub.ended_at = now;
379	  sub.canceled_at ??= now;
380	  sub.cancellation_reason = "cancellation_requested";
381	  sub.cancel_at_period_end = false;
382	  sub.cancel_at = null;
383	}
