114	// ---------------------------------------------------------------- lines
115	
116	export function priceOf(state: State, id: string) {
117	  const p = get(state.prices, id);
118	  if (!p) throw new Error(`unknown price ${id}`);
119	  return p;
120	}
121	
122	export function productName(state: State, priceId: string): string {
123	  const p = priceOf(state, priceId);
124	  return get(state.products, p.product)?.name ?? "";
125	}
126	
127	export function recurringDescription(state: State, priceId: string, quantity: number): string {
128	  const p = priceOf(state, priceId);
129	  return `${quantity} × ${productName(state, priceId)} (at ${money(p.unit_amount)} / ${p.interval})`;
130	}
131	
132	const qtyPrefix = (q: number): string => (q > 1 ? `${q} × ` : "");
133	
134	export function intervalOf(state: State, sub: Subscription): Interval {
135	  const first = sub.items[0];
136	  return first ? priceOf(state, first.price).interval : "month";
137	}
138	
139	// ---------------------------------------------------------------- change plan
140	
141	export interface ItemChange {
142	  id: string;
143	  price: string | null;
144	  quantity: number | null;
145	}
146	
147	export type Behavior = "create_prorations" | "none" | "always_invoice";
148	
149	export interface PlannedItem {
150	  id: string;
151	  price: string;
152	  quantity: number;
153	}
154	
155	export interface Plan {
156	  // Proration lines, without IDs.
157	  prorations: Omit<Line, "id" | "invoice_item">[];
158	  // The discounts each proration line actually carries (for its discount list).
159	  own: DiscSpec[][];
160	  // Per proration line: what a credit line carried (null for a charge), for DSC-07.
161	  carried: (CarriedIds | null)[];
162	  items: PlannedItem[];
163	  // Per planned item: its interval and the end of its current (possibly new) period.
164	  intervals: Interval[];
165	  ends: number[];
166	  // Items whose price or quantity changes.
167	  changed: string[];
168	  // Discounts of the new state (a once coupon passed to the preview included).
169	  discounts: string[];
170	  // Once coupons that took something from the remaining-time charges (spent there).
171	  spent: string[];
172	  immediate: boolean;
173	  // A classic interval change restarts the cycle at the clock time.
174	  reset: boolean;
175	  period_start: number;
176	  // When the preview invoice falls: the earliest item period end (or the reset period's end).
177	  period_end: number;
178	  anchor: number;
179	  proration_date: number;
180	  now: number;
181	}
182	
183	export interface PlanError {
184	  message: string;
185	  param: string | null;
186	}
187	
188	export interface PlanInput {
189	  changes: ItemChange[];
190	  proration_date: number | null;
191	  behavior: Behavior | null;
192	  // Discount IDs replacing the subscription's, or null to keep them.
193	  discounts: string[] | null;
194	  now: number;
195	}
196	
197	interface Carried {
198	  spec: DiscSpec;
199	  amount: number;
200	}
201	
202	// The discounts on the billed line a credit comes from: all of them, and those that took more
203	// than 0 there.
204	export interface CarriedIds {
205	  all: string[];
206	  nonzero: string[];
207	}
208	
209	// Every discount on the line that billed the period, those it got nothing from included.
210	function billedDiscounts(state: State, billed: Billed | null): Carried[] {
211	  if (!billed) return [];
212	  return billed.discounts
213	    .map((d) => ({ spec: specOf(state, d.discount), amount: d.amount }))
214	    .filter((x): x is Carried => x.spec !== undefined);
215	}
216	
217	// Credit for the unused time of an item, from `prd` to the period end, carrying the discounts the
218	// item got on the invoice that billed the period (PRO-01, DSC-04).
219	export function creditLine(
220	  state: State,
221	  sub: Subscription,
222	  it: SubItem,
223	  prd: number,
224	): { line: Omit<Line, "id" | "invoice_item">; own: DiscSpec[]; carried: CarriedIds } {
225	  const oldPrice = priceOf(state, it.price);
226	  const P = sub.period_end - sub.period_start;
227	  const r = sub.period_end - prd;
228	  const b = oldPrice.unit_amount * it.quantity;
229	  const all = billedDiscounts(state, it.billed);
230	  const carried = all.filter((c) => c.amount !== 0);
231	  let credit: number;
232	  let applied: DiscSpec[];
233	  if (sub.billing_mode === "classic") {
234	    // Classic (DSC-04, pass 6): every discount of the billed line, in subscription order, applies
235	    // to the credited item on its own (an amount-off in full, a percent-off on what is left),
236	    // whatever share it got on the billing invoice, 0 included; then the net is prorated.
237	    const D = allocate(
238	      [b],
239	      all.map((c) => c.spec),
240	    ).reduce((a, x) => a + (x[0] ?? 0), 0);
241	    credit = -roundRatio((b - D) * r, P);
242	    applied = all.map((c) => c.spec);
243	  } else {
244	    // Flexible: a carried discount whose prorated amount rounds to 0 is not applied (DSC-08).
245	    const prorated = carried.map((c) => roundRatio(c.amount * r, P));
246	    credit = -(roundRatio(b * r, P) - prorated.reduce((a, x) => a + x, 0));
247	    applied = carried.filter((_, k) => (prorated[k] ?? 0) !== 0).map((c) => c.spec);
248	  }
249	  return {
250	    line: {
251	      amount: credit,
252	      description: `Unused time on ${qtyPrefix(it.quantity)}${productName(state, it.price)}${withDiscounts(applied)} after ${shortDate(prd)}`,
253	      period: { start: prd, end: sub.period_end },
254	      price: it.price,
255	      quantity: it.quantity,
256	      proration: true,
257	      discountable: false,
258	      discount_amounts: [],
259	      subscription_item: it.id,
260	      credited: it.billed ? { invoice: it.billed.invoice, line: it.billed.line } : null,
261	      unit_amount_decimal: null,
262	    },
263	    own: applied,
264	    // Discounts on the billed line, those it got nothing from included (DSC-07).
265	    carried: { all: all.map((c) => c.spec.id), nonzero: carried.map((c) => c.spec.id) },
266	  };
267	}
268	
269	// Classic charge: r/P truncated to a fixed number of decimals, times the amount, half up
270	// (pass 5: 99999999 x 1/18 = 5555555.5 is charged 5555555, 3000 x 0.0075 = 22.5 is charged 23).
271	const CLASSIC_DIGITS = 10n ** 12n;
272	function classicProrate(n: number, r: number, P: number): number {
273	  const f = (BigInt(r) * CLASSIC_DIGITS) / BigInt(P);
274	  const x = BigInt(n) * f;
275	  const sign = x < 0n ? -1n : 1n;
276	  const a = x < 0n ? -x : x;
277	  return Number(sign * ((2n * a + CLASSIC_DIGITS) / (2n * CLASSIC_DIGITS)));
278	}
279	
280	const SAME_INTERVAL =
281	  "All prices on a subscription must have the same `recurring.interval` and `recurring.interval_count` unless flexible billing mode is enabled and you're on the 2025-06-30.basil API version or later. To proceed, update the subscription to flexible billing mode, then retry this update. For information about flexible billing mode, go to https://docs.stripe.com/billing/subscriptions/billing-mode. ";
282	const MIXED_COUPONS =
283	  "Subscriptions with multiple intervals only support percent_off coupons, `duration=once` amount_off coupons, and `duration=repeating` amount_off coupons.";
284	
285	export function planChange(state: State, sub: Subscription, input: PlanInput): Plan | PlanError {
286	  const behavior = input.behavior ?? "create_prorations";
287	  if (behavior === "none" && input.proration_date !== null) {
288	    return {
289	      message: "Cannot specify proration date if no proration is being done",
290	      param: "proration_date",
291	    };
292	  }
293	  const prd = input.proration_date ?? input.now;
294	  if (prd < sub.period_start || prd > sub.period_end) {
295	    return {
296	      message: `Cannot specify proration date outside of current subscription period or current phase. The value should be between ${sub.period_start} and ${sub.period_end}.`,
297	      param: "proration_date",
298	    };
299	  }
300	  const items: PlannedItem[] = sub.items.map((it) => {
301	    const ch = input.changes.find((c) => c.id === it.id);
302	    if (!ch) return { id: it.id, price: it.price, quantity: it.quantity };
303	    const priceChanged = ch.price !== null && ch.price !== it.price;
304	    return {
305	      id: it.id,
306	      price: ch.price ?? it.price,
307	      quantity: ch.quantity ?? (priceChanged ? 1 : it.quantity),
308	    };
309	  });
310	  const oldIntervals = sub.items.map((it) => priceOf(state, it.price).interval);
311	  const intervals = items.map((it) => priceOf(state, it.price).interval);
312	  const discounts =
313	    input.discounts ?? sub.discounts.filter((id) => get(state.discounts, id)?.used !== true);
314	  const chargeSpecs = specsOf(state, discounts);
315	
316	  let periodStart = sub.period_start;
317	  let anchor = sub.anchor;
318	  let reset = false;
319	  let ends = items.map(() => sub.period_end);
320	  const intervalChange = intervals.some((iv, i) => iv !== oldIntervals[i]);
321	  const mixed = new Set(intervals).size > 1;
322	  if (intervalChange) {
323	    if (sub.billing_mode === "classic") {
324	      if (mixed) return { message: SAME_INTERVAL, param: null };
325	      reset = true;
326	      periodStart = input.now;
327	      anchor = input.now;
328	      ends = intervals.map((iv) => addIntervals(input.now, iv, 1));
329	    } else {
330	      if (mixed && chargeSpecs.some((s) => !s.once && s.amount_off !== null)) {
331	        return { message: MIXED_COUPONS, param: null };
332	      }
333	      // Each item keeps its own period; a new interval runs from the current period start.
334	      ends = intervals.map((iv, i) =>
335	        iv === oldIntervals[i] ? sub.period_end : addIntervals(sub.period_start, iv, 1),
336	      );
337	      for (const end of ends) {
338	        if (end < sub.period_end && prd > end) {
339	          return {
340	            message: `You cannot specify \`proration_date\` past the updated subscription period end when using flexible billing mode. The value should be less than ${end}.`,
341	            param: null,
342	          };
343	        }
344	      }
345	    }
346	  }
347	
348	  const prorations: Plan["prorations"] = [];
349	  const own: DiscSpec[][] = [];
350	  const carried: (CarriedIds | null)[] = [];
351	  const spent = new Set<string>();
352	  const changed = sub.items
353	    .filter((it, i) => {
354	      const next = items[i];
355	      return next !== undefined && (next.price !== it.price || next.quantity !== it.quantity);
356	    })
357	    .map((it) => it.id);
358	  if (behavior !== "none") {
359	    sub.items.forEach((it: SubItem, i) => {
360	      const next = items[i];
361	      if (!next || !changed.includes(it.id)) return;
362	      // A credit with no remaining time is omitted (INT-02), and so is the credit of an item
363	      // billed at 0 (pass 5).
364	      const b = priceOf(state, it.price).unit_amount * it.quantity;
365	      if (prd < sub.period_end && b !== 0) {
366	        const credit = creditLine(state, sub, it, prd);
367	        prorations.push(credit.line);
368	        own.push(credit.own);
369	        carried.push(credit.carried);
370	      }
371	      if (reset) return;
372	      // Charge for the remaining time on the new item, over the item's new period.
373	      const end = ends[i] ?? sub.period_end;
374	      const newPrice = priceOf(state, next.price);
375	      const n = newPrice.unit_amount * next.quantity;
376	      const P2 = end - periodStart;
377	      const r2 = end - prd;
378	      const e2 = prd - periodStart;
379	      if (r2 <= 0) return;
380	      const classic = sub.billing_mode === "classic";
381	      // PRO-11: classic bills no remaining time for a new item whose amount is 0.
382	      if (classic && n === 0) return;
383	      const D2 = allocate([n], chargeSpecs).map((x) => x[0] ?? 0);
384	      const factor = 1 - e2 / P2;
385	      const base = classic ? classicProrate(n, r2, P2) : Math.round(n * factor);
386	      // Flexible discounts the full-period amount, then prorates the discount with the charge's
387	      // factor (DSC-02); classic prorates first and takes a percent-off on the prorated amount
388	      // (DSC-04).
389	      let left = base;
390	      const prorated = chargeSpecs.map((s, k) => {
391	        const full = D2[k] ?? 0;
392	        const d = !classic
393	          ? Math.round(full * factor)
394	          : s.percent_off !== null
395	            ? roundRatio(Math.max(0, left) * ppm(s.percent_off), PPM)
396	            : roundRatio(full * r2, P2);
397	        left -= d;
398	        return d;
399	      });
400	      const applied = chargeSpecs.filter((_, k) => (prorated[k] ?? 0) !== 0);
401	      // A once coupon is spent by the charge when its full-period share is above 0, even if the
402	      // prorated share rounds to 0 (pass 8: dev-v5-dsc-013, -052).
403	      chargeSpecs.forEach((s, k) => {
404	        if (s.once && (D2[k] ?? 0) > 0) spent.add(s.id);
405	      });
406	      prorations.push({
407	        amount: left,
408	        description: `Remaining time on ${qtyPrefix(next.quantity)}${productName(state, next.price)}${withDiscounts(applied)} after ${shortDate(prd)}`,
409	        period: { start: prd, end },
410	        price: next.price,
411	        quantity: next.quantity,
412	        proration: true,
413	        discountable: false,
414	        discount_amounts: [],
415	        subscription_item: it.id,
416	        credited: null,
417	        unit_amount_decimal: null,
418	      });
419	      own.push(applied);
420	      carried.push(null);
421	    });
422	  }
423	  const immediate = reset || (behavior === "always_invoice" && prorations.length > 0);
424	  return {
425	    prorations,
426	    own,
427	    carried,
428	    items,
429	    intervals,
430	    ends,
431	    changed,
432	    discounts,
433	    spent: [...spent],
434	    immediate,
435	    reset,
436	    period_start: periodStart,
437	    period_end: Math.min(...ends),
438	    anchor,
439	    proration_date: prd,
440	    now: input.now,
441	  };
442	}
443	
444	export function isPlanError(p: Plan | PlanError): p is PlanError {
445	  return "message" in p;
446	}
