448	// ---------------------------------------------------------------- invoice assembly
449	
450	export interface Draft {
451	  lines: Line[];
452	  discounts: string[];
453	  total_discount_amounts: DiscountAmount[];
454	  created: number;
455	  period_start: number;
456	  period_end: number;
457	  immediate: boolean;
458	}
459	
460	// The invoice a plan produces: now (immediate) or at the next renewal (prorations plus the next
461	// full period of every item whose period ends then).
462	export function draftFromPlan(
463	  state: State,
464	  sub: Subscription,
465	  plan: Plan,
466	  ids: { line: () => string; item: () => string },
467	  mode: Subscription["billing_mode"],
468	): Draft {
469	  // An active once coupon (DSC-05, pass 5) that took something from a remaining-time charge is
470	  // spent there: off the invoice and off the renewal lines. Otherwise it is on the invoice and
471	  // discounts the renewal. An immediate invoice lists it either way (at 0 there).
472	  const top = plan.discounts.filter((id) => {
473	    const s = specOf(state, id);
474	    if (!s) return false;
475	    return !s.once || plan.immediate || !plan.spent.includes(id);
476	  });
477	  const topSpecs = specsOf(state, top);
478	  const lines: Line[] = plan.prorations.map((p) => ({
479	    ...p,
480	    id: ids.line(),
481	    invoice_item: ids.item(),
482	  }));
483	  const recurring: Line[] = [];
484	  if (plan.reset) {
485	    plan.items.forEach((it, i) => {
486	      if (!plan.changed.includes(it.id)) return;
487	      const end = plan.ends[i] ?? plan.period_end;
488	      recurring.push(recurringLine(state, it, plan.period_start, end, ids.line()));
