542	function immediateCreditList(top: string[], carried: CarriedIds, survivors: string[]): string[] {
543	  if (top.length === 0) return [];
544	  // A carried discount that took 0 counts only while it is still on the invoice
545	  // (dev-brk-off1-zero-share-always lists nothing, dev-v5-dsc-116 the invoice's discounts).
546	  const counted = carried.all.filter((id) => carried.nonzero.includes(id) || top.includes(id));
547	  if (counted.length === 0) return top;
548	  if (survivors.length === 0) return [];
549	  const onInvoice = top.filter((id) => survivors.includes(id));
550	  if (onInvoice.length > 0) return onInvoice;
551	  if (carried.all.some((id) => top.includes(id))) return top;
552	  if (carried.all.length === 1) return survivors;
553	  return top;
