581	// The smallest amount the account charges (INV-01): dev-t2-f-left55 is not charged, left56 is.
582	export const MIN_CHARGE = 56;
583	
584	// What an invoice asks for: its total plus the starting balance, less an amount deferred to the
585	// customer balance because it was below the minimum charge.
586	export function amountDue(inv: {
587	  lines: Line[];
588	  total_discount_amounts: DiscountAmount[];
589	  starting_balance: number;
590	  deferred: number;
591	}): number {
592	  const { total } = totals(inv.lines, inv.total_discount_amounts);
593	  return Math.max(0, total + inv.starting_balance) - inv.deferred;
594	}
595	
596	// Charges below the minimum are not attempted: the amount goes to the customer balance.
597	export function deferSmall(state: State, inv: Invoice): boolean {
598	  const due = amountDue(inv);
599	  if (due <= 0 || due >= MIN_CHARGE) return false;
600	  inv.deferred += due;
601	  const c = get(state.customers, inv.customer);
602	  if (c) c.balance += due;
603	  inv.status = "paid";
604	  inv.next_payment_attempt = null;
605	  return true;
606	}
