608	export function totals(lines: Line[], tda: DiscountAmount[]) {
609	  const subtotal = lines.reduce((a, l) => a + l.amount, 0);
610	  const discount = tda.reduce((a, d) => a + d.amount, 0);
611	  return { subtotal, total: subtotal - discount };
612	}
